mapper.select:
select p.id, p.user_id, u.username, u.name, u.dept_id as deptId, d.name as deptName, p.punch_date, p.slot, p.punch_time, p.source, o.name as operatorName from attendance_punch p left join sys_user u on u.id = p.user_id left join sys_dept d on d.id = u.dept_id left join sys_user o on o.id = p.operator_user_id
and p.is_deleted = 0 and exists (select 1 from attendance_group_member m where m.user_id = p.user_id)
and (u.name like CONCAT('%', #{query.name}, '%') or u.username like CONCAT('%', #{query.name}, '%'))
and p.punch_date >= #{query.beginDate}
and p.punch_date <= #{query.endDate}
and p.source = #{query.source}
and (u.dept_id in
#{deptId}
or p.user_id = #{scope.selfUserId}
)
and p.user_id = #{scope.selfUserId}
and 1 = 0
order by p.punch_time desc, p.id desc
